class Solution {
public:
    bool checkValid(vector<vector<int>>& matrix) {
        int n = matrix.size();
        vector<bool> seen(n + 1, false);
        for (int i = 0; i < n; i++) {
            fill(seen.begin(), seen.end(), false);
            for (int j = 0; j < n; j++) {
                seen[matrix[i][j]] = true;
            }
            for (int k = 1; k <= n; k++) {
                if (!seen[k]) return false;
            }
        }
        for (int j = 0; j < n; j++) {
            fill(seen.begin(), seen.end(), false);
            for (int i = 0; i < n; i++) {
                seen[matrix[i][j]] = true;
            }
            for (int k = 1; k <= n; k++) {
                if (!seen[k]) return false;
            }
        }
        return true;
    }
};
